<?php $pageTitle='Search';require_once __DIR__.'/functions.php';$q=trim($_GET['q']??'');$results=[];if($q!==''){ $like='%'.$q.'%';$st=db()->prepare("SELECT title,description,'Course' type,CONCAT('course.php?slug=',slug) url FROM courses WHERE title LIKE ? OR description LIKE ? UNION ALL SELECT title,description,'Tutorial',COALESCE(url,'#') FROM tutorials WHERE title LIKE ? OR description LIKE ? UNION ALL SELECT title,description,'Resource',file_path FROM resources WHERE title LIKE ? OR description LIKE ? UNION ALL SELECT title,description,'Application',file_path FROM applications WHERE title LIKE ? OR description LIKE ? ORDER BY title");$st->execute([$like,$like,$like,$like,$like,$like,$like,$like]);$results=$st->fetchAll();}include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Search</h1><p class="muted">Results for “<?=e($q)?>”</p></div></section><section class="section" style="padding-top:10px"><div class="container search-results"><?php if(!$results):?><div class="panel"><h3>No results found</h3><p class="muted">Try computer, web, PHP, PDF or application name.</p></div><?php else:foreach($results as $r):?><div class="resource"><div><div class="meta"><span><?=e($r['type'])?></span></div><h3><?=e($r['title'])?></h3><p class="muted"><?=e($r['description'])?></p></div><a class="primary" href="<?=e($r['url'])?>">Open</a></div><?php endforeach;endif;?></div></section><?php include 'includes/footer.php';?>
